package com.amit.jobagent.application;import jakarta.persistence.*;import java.util.UUID;
@Entity @Table(name="generated_claim_source")class GeneratedClaimSource{@Id UUID id;@Column(name="generated_claim_id",nullable=false,updatable=false)UUID claimId;@Column(name="candidate_fact_id",updatable=false)UUID factId;@Column(name="candidate_snapshot_evidence_id",updatable=false)UUID snapshotEvidenceId;@Column(name="job_requirement_id",updatable=false)UUID requirementId;@Column(name="job_field_reference",updatable=false,length=100)String jobField;protected GeneratedClaimSource(){}GeneratedClaimSource(UUID claim,UUID fact,UUID requirement,String field){this(claim,fact,null,requirement,field);}private GeneratedClaimSource(UUID claim,UUID fact,UUID snapshotEvidence,UUID requirement,String field){id=UUID.randomUUID();claimId=claim;factId=fact;snapshotEvidenceId=snapshotEvidence;requirementId=requirement;jobField=field;}static GeneratedClaimSource fromSnapshotEvidence(UUID claim,UUID evidence){return new GeneratedClaimSource(claim,null,evidence,null,null);}UUID candidateEvidenceId(){return snapshotEvidenceId==null?factId:snapshotEvidenceId;}}
